"""E146 prediction report with explicit scope and links to recorded source videos."""
import shutil
from pathlib import Path
from .calibration_prior_learning import ROOT
from .abstaining_task_value_gate import read,save,fingerprint

def run():
    s=read(ROOT/'summary.json');v=read(ROOT/'verification.json');assert v['all_predictions_exact'];m=s['metrics'];lines=['# E146: learned weighting around measured calibration','','The model learns relative weights for32 measured transitions while retaining a fixed measured calibration prior in weakly excited directions. This is a Transformer plus explicit weighted least-squares solve, not a flow-matching policy. No exact robot Jacobian, object/contact truth or task-success label is used for training.','',f"{v['transitions']} correlated transitions from {v['placements']} fitting placements; four original ancestry-family folds and three fixed seeds. Sampling balances placements; all three Jacobians are averaged for the primary ensemble. No seed or checkpoint selection.",'','| Estimator | All position RMSE (mm) | Six joints | Seven joints | Scaled rotation RMSE (mm) |','|---|---:|---:|---:|---:|']
    for name,x in m.items():lines.append(f"| {name} | {x['all']['position_rmse_mm']:.4f} | {x['6']['position_rmse_mm']:.4f} | {x['7']['position_rmse_mm']:.4f} | {x['all']['rotation_rmse_mm']:.4f} |")
    ratio=(m['ensemble']['all']['position_rmse_mm']/m['reference']['all']['position_rmse_mm'])**2;lines += ['',f"Primary ensemble lowers position MSE by {(1-ratio)*100:.1f}%; all three individual models also improve overall, and both joint counts improve. Fixed prediction screen passes: {s['qualifies_for_control']}. This only authorizes a complete fitting-controller test. Earlier studies showed lower prediction error can still reduce task success; no task gain is claimed here.",'','Actual future joint motion is a supervised query and never a network input. The network observes only past history and residuals against measured initial calibration. Orientation errors use .15 times tool-axis-vector increments, not angle units. Priors, independent NumPy reference solves, family exclusion, placement-balanced sampling, training-only scales, normalized weight mass, all predictions and source hashes were independently verified. E120 remains unchanged.','', 'Source-context successes and failures are in [E144](../ease_history_estimator_control_v1/videos/index.html); the matched analytical-prior control is in [E145](../ease_calibration_prior_control_v1/videos/index.html). These are not learned-prior controller demonstrations. E147 saves those separately.','']
    (ROOT/'report.md').write_text('\n'.join(lines));p=Path(__file__).with_name('TECHNICAL_REPORT.md');text=p.read_text(encoding='utf-8');assert '## E146:' not in text;p.write_text(text+'\n## E146: learned calibration-prior history weights\n\n'+lines[-5]+f' Report: `{ROOT}/report.md`.\n',encoding='utf-8')
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    fig,ax=plt.subplots(figsize=(7,4));ax.bar(['Measured calibration prior','Learned fixed ensemble'],[m['reference']['all']['position_rmse_mm'],m['ensemble']['all']['position_rmse_mm']]);ax.set_ylabel('Position RMSE (mm)');ax.set_title('E146 | excluded fitting families | prediction only');fig.tight_layout();fig.savefig(ROOT/'comparison.png',dpi=150);plt.close(fig);shutil.copy2(__file__,ROOT/'source'/Path(__file__).name);save(ROOT/'artifact_hashes.json',{str(p.relative_to(ROOT)):fingerprint(p) for p in ROOT.rglob('*') if p.is_file() and p.name!='artifact_hashes.json'});print('E146 report archived',flush=True)

if __name__=='__main__':run()
